window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6245b9b175d08eb5"]={"versions": [{"id": "FIG-6245b9b175d08eb5", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Ausschnitt (UML-Klassendiagramm), spezifiziert in <code>AUTOSAR_TPS_TimingExtensions</code> (R20-11).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Modellierung der strukturellen Integration von Software-Clustern der Classic Platform (<code>CpSoftwareCluster</code>) in das Gesamtsystem (<code>System</code>).</li>\n<li>Dient der logischen und physikalischen Kapselung von Software-Komponenten (SWCs) für modulare Update-Konzepte (OTA / Software Cluster Updates), Multicore-/Partitionierungs-Strategien und herstellerübergreifendes Deployment.</li>\n<li>Ermöglicht sowohl eine grobgranulare Zuweisung kompletter Kompositionen als auch eine instanzgenaue Zuweisung einzelner SWC-Prototypen zu separaten Clustern.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>):</li>\n</ul>\n<p class=\"fig-p\">Wurzelelement der Systemkonfiguration.</p>\n<ul class=\"fig-list\">\n<li><em>Attribute:</em></li>\n<li><code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code> – Endianness des Headers für Container-I-PDUs.</li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code> – Versionsstand des abgeleiteten ECU-Extracts.</li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code> & <code>pncVectorOffset: PositiveInteger [0..1]</code> – Dimensionierung und Offset des Partial-Network-Cluster-Bitvektors.</li>\n<li><code>systemVersion: RevisionLabelString [1]</code> – Version der System Description.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):</li>\n</ul>\n<p class=\"fig-p\">Top-Level-Prototyp der gesamten Software-Architektur des Systems.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompositionSwComponentType</code></strong> (<code>«SwComponentType»</code>):</li>\n</ul>\n<p class=\"fig-p\">Hierarchischer Kompositionstyp, der Sub-Komponenten bündelt.</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):</li>\n</ul>\n<p class=\"fig-p\">Konkrete Komponenten-Instanz innerhalb einer Komposition.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CpSoftwareCluster</code></strong> (<code>«ARElement»</code>):</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert die Kapselungseinheit für Classic Platform Software-Cluster (<code>mmt.RestrictToStandards = CP</code>, <code>atp.Status = draft</code>).</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwComponentPrototypeAssignment</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Dediziertes Mapping-Element zur feingranularen Zuweisung eines Komponenten-Prototyps zu einem Cluster via Instanzreferenz.</p>\n<p class=\"fig-p\">#### Beziehungen, Kardinalitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code> ➔ <code>RootSwCompositionPrototype</code> (<code>+rootSoftwareComposition</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>. Definiert die primäre Software-Komposition des Systems.</p>\n<ul class=\"fig-list\">\n<li><strong><code>RootSwCompositionPrototype</code> ➔ <code>CompositionSwComponentType</code> (<code>+softwareComposition</code>, 1):</strong></li>\n</ul>\n<p class=\"fig-p\">Typisierung via <code>«isOfType»</code> unter <code>{redefines atpType}</code>.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>CompositionSwComponentType</code> ➔ <code>SwComponentPrototype</code> (<code>+component</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>. Enthält die Komponentenprototypen des Software-Designs.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>System</code> ➔ <code>CpSoftwareCluster</code> (<code>+swCluster</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Referenzierende Aggregation mit <code>«atpSplitable, atpVariation»</code>. Bindet beliebig viele Cluster an das System.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>CpSoftwareCluster</code> ➔ <code>CompositionSwComponentType</code> (<code>+swComposition</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Assoziation mit <code>«atpVariation, atpSplitable»</code>.</p>\n<ul class=\"fig-list\">\n<li><em>Tag:</em> <code>vh.latestBindingTime = systemDesignTime</code>. Ganze Kompositionsstrukturen werden früh zur Systementwurfszeit an den Cluster gebunden.</li>\n<li>*<em><code>CpSoftwareCluster</code> ➔ <code>SwComponentPrototypeAssignment</code> (<code>+swComponentAssignment</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>.</p>\n<ul class=\"fig-list\">\n<li><em>Tag:</em> <code>vh.latestBindingTime = postBuild</code>. Erlaubt späte, instanzbezogene Cluster-Zuordnungen bis zur Post-Build-Phase.</li>\n<li><strong><code>SwComponentPrototypeAssignment</code> ➔ <code>SwComponentPrototype</code> (<code>+swComponent</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Gerichtete Instanzreferenz (<code>«instanceRef»</code>). Adressiert einen spezifischen Komponentenprototypen über den hierarchischen Kompositionspfad.</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein M2-Klassendiagramm der Informationsarchitektur handelt, existiert kein Ausführungsablauf zur CPU-Laufzeit. Der methodische Verarbeitungsablauf im AUTOSAR-Workflow gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>System Design Time:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Modellierung der VFB-Architektur (<code>RootSwCompositionPrototype</code>, <code>CompositionSwComponentType</code>).</li>\n<li>Grobe Cluster-Zuweisung vollständiger Funktionsbündel über <code>CpSoftwareCluster.swComposition</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ECU Partitioning & Post-Build Configuration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Bindung einzelner Komponentenprototypen über <code>SwComponentPrototypeAssignment</code> (<code>«instanceRef»</code>).</li>\n<li>Auflösung von Varianten (<code>atpVariation</code>) bis zur Bindungszeit <code>postBuild</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Build & Toolchain:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Extraktion der Cluster-Artefakte für getrennte RTE-, OS- und Memory-Protection-Generierung pro Cluster.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicher- & Ausführungskapselung:</strong></li>\n<li>Jedes <code>CpSoftwareCluster</code> korreliert auf ECU-Ebene typischerweise mit einer eigenen Memory Partition (MPU/MMU-Schutzgrenzen), OS-Application oder einem dedizierten Core.</li>\n<li>Entwickler müssen berücksichtigen, dass Schnittstellen zwischen SWCs innerhalb desselben Clusters (intra-cluster) performanceoptimiert (z. B. direkte Funktionsaufrufe/Macros) ablaufen können, während clusterübergreifende Schnittstellen (inter-cluster) zwingend über RTE-Proxy-Mechanismen, IOC (Inter-OS-Application Communicator) oder IPC entkoppelt werden.</li>\n<li><strong>Variantenbindung & Tooling:</strong></li>\n<li>Das Vorhandensein zweier Bindungszeitpunkte (<code>systemDesignTime</code> für <code>swComposition</code> vs. <code>postBuild</code> für <code>swComponentAssignment</code>) erfordert strikte Einhaltung der Modellierungsregeln: Kompositionstypen können nach dem Systementwurf nicht mehr dynamisch umgehängt werden; spezifische Komponenteninstanzen können hingegen post-build variiert werden.</li>\n<li><strong>Instanzreferenzierung (<code>«instanceRef»</code>):</strong></li>\n<li>Generatoren müssen sicherstellen, dass die <code>SwComponentPrototypeAssignment</code> einen eindeutigen Kontextpfad durch den Kompositionsbaum bis zum Zielprototypen besitzt, um Fehlallokationen bei mehrfach instanziierten SWC-Typen zu verhindern.</li>\n<li><strong>Metamodell-Reifegrad (R20-11):</strong></li>\n<li>Gekennzeichnet mit <code>atp.Status = draft</code> und <code>mmt.RestrictToStandards = CP</code>: Der Standard definiert das Feature explizit für Classic Platform, befindet sich in R20-11 jedoch noch im Entwurfsstatus, was herstellerspezifische Tool-Einschränkungen (RTE-/BswM-Generatoren) zur Folge haben kann.</li>\n</ul>"}, {"id": "FIG-f47a9b1b798782f7", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Ausschnitt (UML-Klassendiagramm), spezifiziert in <code>AUTOSAR_TPS_TimingExtensions</code> (R20-11).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Modellierung der strukturellen Integration von Software-Clustern der Classic Platform (<code>CpSoftwareCluster</code>) in das Gesamtsystem (<code>System</code>).</li>\n<li>Dient der logischen und physikalischen Kapselung von Software-Komponenten (SWCs) für modulare Update-Konzepte (OTA / Software Cluster Updates), Multicore-/Partitionierungs-Strategien und herstellerübergreifendes Deployment.</li>\n<li>Ermöglicht sowohl eine grobgranulare Zuweisung kompletter Kompositionen als auch eine instanzgenaue Zuweisung einzelner SWC-Prototypen zu separaten Clustern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>):</li>\n</ul>\n<p class=\"fig-p\">Wurzelelement der Systemkonfiguration.</p>\n<ul class=\"fig-list\">\n<li><em>Attribute:</em></li>\n<li><code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code> – Endianness des Headers für Container-I-PDUs.</li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code> – Versionsstand des abgeleiteten ECU-Extracts.</li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code> & <code>pncVectorOffset: PositiveInteger [0..1]</code> – Dimensionierung und Offset des Partial-Network-Cluster-Bitvektors.</li>\n<li><code>systemVersion: RevisionLabelString</code> – Version der System Description (Multiplizität 1).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):</li>\n</ul>\n<p class=\"fig-p\">Top-Level-Prototyp der gesamten Software-Architektur des Systems.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompositionSwComponentType</code></strong> (<code>«SwComponentType»</code>):</li>\n</ul>\n<p class=\"fig-p\">Hierarchischer Kompositionstyp, der Sub-Komponenten bündelt.</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):</li>\n</ul>\n<p class=\"fig-p\">Konkrete Komponenten-Instanz innerhalb einer Komposition.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CpSoftwareCluster</code></strong> (<code>«ARElement»</code>):</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert die Kapselungseinheit für Classic Platform Software-Cluster (<code>mmt.RestrictToStandards = CP</code>, <code>atp.Status = draft</code>).</p>\n<ul class=\"fig-list\">\n<li><em>Attribute:</em></li>\n<li><code>softwareClusterId: PositiveInteger [0..1]</code> – Optionale eindeutige numerische Kennung des Software-Clusters.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>SwComponentPrototypeAssignment</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Dediziertes Mapping-Element zur feingranularen Zuweisung eines Komponenten-Prototyps zu einem Cluster via Instanzreferenz.</p>\n<p class=\"fig-p\">#### Beziehungen, Kardinalitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code> ➔ <code>RootSwCompositionPrototype</code> (<code>+rootSoftwareComposition</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>. Definiert die primäre Software-Komposition des Systems.</p>\n<ul class=\"fig-list\">\n<li><strong><code>RootSwCompositionPrototype</code> ➔ <code>CompositionSwComponentType</code> (<code>+softwareComposition</code>, 1):</strong></li>\n</ul>\n<p class=\"fig-p\">Typisierung via <code>«isOfType»</code> unter <code>{redefines atpType}</code>.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>CompositionSwComponentType</code> ➔ <code>SwComponentPrototype</code> (<code>+component</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>. Enthält die Komponentenprototypen des Software-Designs.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>System</code> ➔ <code>CpSoftwareCluster</code> (<code>+swCluster</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Referenzierende Aggregation mit <code>«atpSplitable, atpVariation»</code>. Bindet beliebig viele Cluster an das System.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>CpSoftwareCluster</code> ➔ <code>CompositionSwComponentType</code> (<code>+swComposition</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Assoziation mit <code>«atpVariation, atpSplitable»</code>.</p>\n<ul class=\"fig-list\">\n<li><em>Tag:</em> <code>vh.latestBindingTime = systemDesignTime</code>. Ganze Kompositionsstrukturen werden früh zur Systementwurfszeit an den Cluster gebunden.</li>\n<li>*<em><code>CpSoftwareCluster</code> ➔ <code>SwComponentPrototypeAssignment</code> (<code>+swComponentAssignment</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>.</p>\n<ul class=\"fig-list\">\n<li><em>Tag:</em> <code>vh.latestBindingTime = postBuild</code>. Erlaubt späte, instanzbezogene Cluster-Zuordnungen bis zur Post-Build-Phase.</li>\n<li><strong><code>SwComponentPrototypeAssignment</code> ➔ <code>SwComponentPrototype</code> (<code>+swComponent</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Gerichtete Assoziation via Instanzreferenz (<code>«instanceRef»</code>). Referenziert den spezifischen Komponenten-Prototyp im Architekturbaum.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein M2-Klassendiagramm der Informationsarchitektur handelt, existiert kein Ausführungsablauf zur CPU-Laufzeit. Der methodische Verarbeitungsablauf im AUTOSAR-Workflow gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>System Design Time:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Modellierung der VFB-Architektur (<code>RootSwCompositionPrototype</code>, <code>CompositionSwComponentType</code>).</li>\n<li>Grobe Cluster-Zuweisung vollständiger Funktionsbündel über <code>CpSoftwareCluster.swComposition</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ECU Partitioning & Post-Build Configuration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Bindung einzelner Komponentenprototypen über <code>SwComponentPrototypeAssignment</code> (<code>«instanceRef»</code>).</li>\n<li>Auflösung von Varianten (<code>atpVariation</code>) bis zur Bindungszeit <code>postBuild</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Build & Toolchain:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Extraktion der Cluster-Artefakte für getrennte RTE-, OS- und Memory-Protection-Generierung pro Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicher- & Ausführungskapselung:</strong></li>\n<li>Jedes <code>CpSoftwareCluster</code> korreliert auf ECU-Ebene typischerweise mit einer eigenen Memory Partition (MPU/MMU-Schutzgrenzen), OS-Application oder einem dedizierten Core.</li>\n<li>Entwickler müssen berücksichtigen, dass Schnittstellen zwischen SWCs innerhalb desselben Clusters (intra-cluster) performanceoptimiert (z. B. direkte Funktionsaufrufe/Macros) ablaufen können, während clusterübergreifende Schnittstellen (inter-cluster) zwingend über RTE-Proxy-Mechanismen, IOC (Inter-OS-Application Communicator) oder IPC entkoppelt werden.</li>\n<li><strong>Variantenbindung & Tooling:</strong></li>\n<li>Das Vorhandensein zweier Bindungszeitpunkte (<code>systemDesignTime</code> für <code>swComposition</code> vs. <code>postBuild</code> für <code>swComponentAssignment</code>) erfordert strikte Einhaltung der Modellierungsregeln: Kompositionstypen können nach dem Systementwurf nicht mehr dynamisch umgehängt werden; spezifische Komponenteninstanzen können hingegen post-build variiert werden.</li>\n<li><strong>Instanzreferenzierung (<code>«instanceRef»</code>):</strong></li>\n<li>Generatoren müssen sicherstellen, dass die <code>SwComponentPrototypeAssignment</code> einen eindeutigen Kontextpfad durch den Kompositionsbaum bis zum Zielprototypen besitzt, um Fehlallokationen bei mehrfach instanziierten SWC-Typen zu verhindern.</li>\n<li><strong>Metamodell-Reifegrad (R20-11):</strong></li>\n<li>Gekennzeichnet mit <code>atp.Status = draft</code> und <code>mmt.RestrictToStandards = CP</code>: Der Standard definiert das Feature explizit für Classic Platform, befindet sich in R20-11 jedoch noch im Entwurfsstatus, was herstellerspezifische Tool-Einschränkungen (RTE-/BswM-Generatoren) zur Folge haben kann.</li>\n</ul>"}, {"id": "FIG-1cd4117d26638a32", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Ausschnitt (UML-Klassendiagramm), spezifiziert in <code>AUTOSAR_TPS_TimingExtensions</code> (R20-11).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Modellierung der strukturellen Integration von Software-Clustern der Classic Platform (<code>CpSoftwareCluster</code>) in das Gesamtsystem (<code>System</code>).</li>\n<li>Dient der logischen und physikalischen Kapselung von Software-Komponenten (SWCs) für modulare Update-Konzepte (OTA / Software Cluster Updates), Multicore-/Partitionierungs-Strategien und herstellerübergreifendes Deployment.</li>\n<li>Ermöglicht sowohl eine grobgranulare Zuweisung kompletter Kompositionen als auch eine instanzgenaue Zuweisung einzelner SWC-Prototypen zu separaten Clustern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>, <code>«UploadableDesignElement»</code>):</li>\n</ul>\n<p class=\"fig-p\">Wurzelelement der Systemkonfiguration.</p>\n<ul class=\"fig-list\">\n<li><em>Attribute:</em></li>\n<li><code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code> – Endianness des Headers für Container-I-PDUs.</li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code> – Versionsstand des abgeleiteten ECU-Extracts.</li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code> & <code>pncVectorOffset: PositiveInteger [0..1]</code> – Dimensionierung und Offset des Partial-Network-Cluster-Bitvektors.</li>\n<li><code>systemVersion: RevisionLabelString [0..1]</code> – Optionale Version der System Description.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):</li>\n</ul>\n<p class=\"fig-p\">Top-Level-Prototyp der gesamten Software-Architektur des Systems.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompositionSwComponentType</code></strong> (<code>«SwComponentType»</code>):</li>\n</ul>\n<p class=\"fig-p\">Hierarchischer Kompositionstyp, der Sub-Komponenten bündelt.</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):</li>\n</ul>\n<p class=\"fig-p\">Konkrete Komponenten-Instanz innerhalb einer Komposition.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CpSoftwareCluster</code></strong> (<code>«ARElement»</code>):</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert die Kapselungseinheit für Classic Platform Software-Cluster (<code>mmt.RestrictToStandards = CP</code>).</p>\n<ul class=\"fig-list\">\n<li><em>Attribute:</em></li>\n<li><code>softwareClusterId: PositiveInteger [0..1]</code> – Optionale eindeutige numerische Kennung des Software-Clusters.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>SwComponentPrototypeAssignment</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Dediziertes Mapping-Element zur feingranularen Zuweisung eines Komponenten-Prototyps zu einem Cluster via Instanzreferenz.</p>\n<p class=\"fig-p\">#### Beziehungen, Kardinalitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code> ➔ <code>RootSwCompositionPrototype</code> (<code>+rootSoftwareComposition</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>. Definiert die primäre Software-Komposition des Systems.</p>\n<ul class=\"fig-list\">\n<li><strong><code>RootSwCompositionPrototype</code> ➔ <code>CompositionSwComponentType</code> (<code>+softwareComposition</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Typisierung via <code>«isOfType»</code> unter <code>{redefines atpType}</code> mit Multiplizität 0..1.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>CompositionSwComponentType</code> ➔ <code>SwComponentPrototype</code> (<code>+component</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>. Enthält die Komponentenprototypen des Software-Designs.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>System</code> ➔ <code>CpSoftwareCluster</code> (<code>+swCluster</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Referenzierende Aggregation mit <code>«atpSplitable, atpVariation»</code>. Bindet beliebig viele Cluster an das System.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>CpSoftwareCluster</code> ➔ <code>CompositionSwComponentType</code> (<code>+swComposition</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Assoziation mit <code>«atpVariation, atpSplitable»</code>.</p>\n<ul class=\"fig-list\">\n<li><em>Tag:</em> <code>vh.latestBindingTime = systemDesignTime</code>. Ganze Kompositionsstrukturen werden früh zur Systementwurfszeit an den Cluster gebunden.</li>\n<li>*<em><code>CpSoftwareCluster</code> ➔ <code>SwComponentPrototypeAssignment</code> (<code>+swComponentAssignment</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>.</p>\n<ul class=\"fig-list\">\n<li><em>Tag:</em> <code>vh.latestBindingTime = postBuild</code>. Erlaubt späte, instanzbezogene Cluster-Zuordnungen bis zur Post-Build-Phase.</li>\n<li><strong><code>SwComponentPrototypeAssignment</code> ➔ <code>SwComponentPrototype</code> (<code>+swComponent</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Gerichtete Assoziation via Instanzreferenz (<code>«instanceRef»</code>). Referenziert den spezifischen Komponenten-Prototyp im Architekturbaum.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein M2-Klassendiagramm der Informationsarchitektur handelt, existiert kein Ausführungsablauf zur CPU-Laufzeit. Der methodische Verarbeitungsablauf im AUTOSAR-Workflow gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>System Design Time:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Modellierung der VFB-Architektur (<code>RootSwCompositionPrototype</code>, <code>CompositionSwComponentType</code>).</li>\n<li>Grobe Cluster-Zuweisung vollständiger Funktionsbündel über <code>CpSoftwareCluster.swComposition</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ECU Partitioning & Post-Build Configuration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Bindung einzelner Komponentenprototypen über <code>SwComponentPrototypeAssignment</code> (<code>«instanceRef»</code>).</li>\n<li>Auflösung von Varianten (<code>atpVariation</code>) bis zur Bindungszeit <code>postBuild</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Build & Toolchain:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Extraktion der Cluster-Artefakte für getrennte RTE-, OS- und Memory-Protection-Generierung pro Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Gültigkeit & Normativer Kontext:</strong> Die Modellierung definiert die formale Struktur zur Abbildung von Software-Clustern der Classic Platform (<code>mmt.RestrictToStandards = CP</code>) innerhalb einer AUTOSAR-Systembeschreibung (<code>System</code>). Das <code>System</code> ist zudem als <code>«UploadableDesignElement»</code> qualifiziert.</li>\n<li><strong>Optionale Wurzelelemente:</strong> Sowohl die Versionsangabe des Gesamtsystems (<code>systemVersion</code>) als auch die Typisierung der Software-Wurzelkomposition (<code>+softwareComposition</code>) besitzen die Kardinalität <code>0..1</code>, was eine flexible, schrittweise Befüllung des Metamodells im Systementwurf erlaubt.</li>\n<li><strong>Variabilitätsmanagement:</strong> Sowohl die Aggregation der Cluster am System (<code>+swCluster</code>) als auch die Zuordnungen von Kompositionen (<code>+swComposition</code>) und Komponenten-Prototypen (<code>+swComponentAssignment</code>) sind als <code>«atpSplitable»</code> und <code>«atpVariation»</code> modelliert. Cluster-Definitionen können somit über mehrere ARXML-Dateien fragmentiert und über Systemvarianten hinweg konditioniert werden.</li>\n<li><strong>Instanzreferenzen:</strong> Bei <code>SwComponentPrototypeAssignment</code> handelt es sich um eine Instanzreferenz (<code>«instanceRef»</code>) auf einen <code>SwComponentPrototype</code>, die den vollen hierarchischen Kontext innerhalb der Wurzelkomposition auflösen muss.</li>\n</ul>"}, {"id": "FIG-5ec3261557780e43", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Ausschnitt (UML-Klassendiagramm), spezifiziert in <code>AUTOSAR_TPS_TimingExtensions</code> (R20-11).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Modellierung der strukturellen Integration von Software-Clustern der Classic Platform (<code>CpSoftwareCluster</code>) in das Gesamtsystem (<code>System</code>).</li>\n<li>Dient der logischen und physikalischen Kapselung von Software-Komponenten (SWCs) für modulare Update-Konzepte (OTA / Software Cluster Updates), Multicore-/Partitionierungs-Strategien und herstellerübergreifendes Deployment.</li>\n<li>Ermöglicht sowohl eine grobgranulare Zuweisung kompletter Kompositionen als auch eine instanzgenaue Zuweisung einzelner SWC-Prototypen zu separaten Clustern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>, <code>«UploadableDesignElement»</code>):</li>\n</ul>\n<p class=\"fig-p\">Wurzelelement der Systemkonfiguration.</p>\n<ul class=\"fig-list\">\n<li><em>Attribute:</em></li>\n<li><code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code> – Endianness des Headers für Container-I-PDUs.</li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code> – Versionsstand des abgeleiteten ECU-Extracts.</li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code> & <code>pncVectorOffset: PositiveInteger [0..1]</code> – Dimensionierung und Offset des Partial-Network-Cluster-Bitvektors.</li>\n<li><code>systemVersion: RevisionLabelString [0..1]</code> – Optionale Version der System Description.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):</li>\n</ul>\n<p class=\"fig-p\">Top-Level-Prototyp der gesamten Software-Architektur des Systems.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompositionSwComponentType</code></strong> (<code>«SwComponentType»</code>):</li>\n</ul>\n<p class=\"fig-p\">Hierarchischer Kompositionstyp, der Sub-Komponenten bündelt.</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):</li>\n</ul>\n<p class=\"fig-p\">Konkrete Komponenten-Instanz innerhalb einer Komposition.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CpSoftwareCluster</code></strong> (<code>«ARElement»</code>):</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert die Kapselungseinheit für Classic Platform Software-Cluster (<code>mmt.RestrictToStandards = CP</code>).</p>\n<ul class=\"fig-list\">\n<li><em>Attribute:</em></li>\n<li><code>softwareClusterId: PositiveInteger [0..1]</code> – Optionale eindeutige numerische Kennung des Software-Clusters.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>SwComponentPrototypeAssignment</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Dediziertes Mapping-Element zur feingranularen Zuweisung eines Komponenten-Prototyps zu einem Cluster via Instanzreferenz.</p>\n<p class=\"fig-p\">#### Beziehungen, Kardinalitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code> ➔ <code>RootSwCompositionPrototype</code> (<code>+rootSoftwareComposition</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>. Definiert die primäre Software-Komposition des Systems.</p>\n<ul class=\"fig-list\">\n<li><strong><code>RootSwCompositionPrototype</code> ➔ <code>CompositionSwComponentType</code> (<code>+softwareComposition</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Typisierung via <code>«isOfType»</code> unter <code>{redefines atpType}</code> mit Multiplizität 0..1.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>CompositionSwComponentType</code> ➔ <code>SwComponentPrototype</code> (<code>+component</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>. Enthält die Komponentenprototypen des Software-Designs.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>System</code> ➔ <code>CpSoftwareCluster</code> (<code>+swCluster</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Referenzierende Aggregation mit <code>«atpSplitable, atpVariation»</code>. Bindet beliebig viele Cluster an das System.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>CpSoftwareCluster</code> ➔ <code>CompositionSwComponentType</code> (<code>+swComposition</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Assoziation mit <code>«atpVariation, atpSplitable»</code>.</p>\n<ul class=\"fig-list\">\n<li><em>Tag:</em> <code>vh.latestBindingTime = systemDesignTime</code>. Ganze Kompositionsstrukturen werden früh zur Systementwurfszeit an den Cluster gebunden.</li>\n<li>*<em><code>CpSoftwareCluster</code> ➔ <code>SwComponentPrototypeAssignment</code> (<code>+swComponentAssignment</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>.</p>\n<ul class=\"fig-list\">\n<li><em>Tag:</em> <code>vh.latestBindingTime = postBuild</code>. Erlaubt späte, instanzbezogene Cluster-Zuordnungen bis zur Post-Build-Phase.</li>\n<li><strong><code>SwComponentPrototypeAssignment</code> ➔ <code>SwComponentPrototype</code> (<code>+swComponent</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Gerichtete Assoziation via Instanzreferenz (<code>«instanceRef»</code>). Referenziert den spezifischen Komponenten-Prototyp im Architekturbaum.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein M2-Klassendiagramm der Informationsarchitektur handelt, existiert kein Ausführungsablauf zur CPU-Laufzeit. Der methodische Verarbeitungsablauf im AUTOSAR-Workflow gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>System Design Time:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Modellierung der VFB-Architektur (<code>RootSwCompositionPrototype</code>, <code>CompositionSwComponentType</code>).</li>\n<li>Grobe Cluster-Zuweisung vollständiger Funktionsbündel über <code>CpSoftwareCluster.swComposition</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ECU Partitioning & Post-Build Configuration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Bindung einzelner Komponentenprototypen über <code>SwComponentPrototypeAssignment</code> (<code>«instanceRef»</code>).</li>\n<li>Auflösung von Varianten (<code>atpVariation</code>) bis zur Bindungszeit <code>postBuild</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Build & Toolchain:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Extraktion der Cluster-Artefakte für getrennte RTE-, OS- und Memory-Protection-Generierung pro Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Gültigkeit & Normativer Kontext:</strong> Die Modellierung definiert die formale Struktur zur Abbildung von Software-Clustern der Classic Platform (<code>mmt.RestrictToStandards = CP</code>) innerhalb einer AUTOSAR-Systembeschreibung (<code>System</code>). Das <code>System</code> ist zudem als <code>«UploadableDesignElement»</code> qualifiziert.</li>\n<li><strong>Optionale Wurzelelemente:</strong> Sowohl die Versionsangabe des Gesamtsystems (<code>systemVersion</code>) als auch die Typisierung der Software-Wurzelkomposition (<code>+softwareComposition</code>) besitzen die Kardinalität <code>0..1</code>, was eine flexible, schrittweise Befüllung des Metamodells im Systementwurf erlaubt.</li>\n<li><strong>Variabilitätsmanagement:</strong> Sowohl die Aggregation der Cluster am System (<code>+swCluster</code>) als auch die Zuordnungen von Kompositionen (<code>+swComposition</code>) und Komponenten-Prototypen (<code>+swComponentAssignment</code>) sind als <code>«atpSplitable»</code> und <code>«atpVariation»</code> modelliert. Cluster-Definitionen können somit über mehrere ARXML-Dateien fragmentiert und über Systemvarianten hinweg konditioniert werden.</li>\n<li><strong>Instanzreferenzen:</strong> Bei <code>SwComponentPrototypeAssignment</code> handelt es sich um eine Instanzreferenz (<code>«instanceRef»</code>) auf einen <code>SwComponentPrototype</code>, die den vollen hierarchischen Kontext innerhalb der Wurzelkomposition auflösen muss.</li>\n</ul>"}, {"id": "FIG-8425c712128c68a7", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Ausschnitt (UML-Klassendiagramm), spezifiziert in <code>AUTOSAR_TPS_TimingExtensions</code> (R20-11).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Modellierung der strukturellen Integration von Software-Clustern der Classic Platform (<code>CpSoftwareCluster</code>) in das Gesamtsystem (<code>System</code>).</li>\n<li>Dient der logischen und physikalischen Kapselung von Software-Komponenten (SWCs) für modulare Update-Konzepte (OTA / Software Cluster Updates), Multicore-/Partitionierungs-Strategien und herstellerübergreifendes Deployment.</li>\n<li>Ermöglicht sowohl eine grobgranulare Zuweisung kompletter Kompositionen als auch eine instanzgenaue Zuweisung einzelner SWC-Prototypen zu separaten Clustern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>, <code>«UploadableDesignElement»</code>):</li>\n</ul>\n<p class=\"fig-p\">Wurzelelement der Systemkonfiguration.</p>\n<ul class=\"fig-list\">\n<li><em>Attribute:</em></li>\n<li><code>containerIPduHeaderByteOrder: ByteOrderEnum [0..1]</code> – Endianness des Headers für Container-I-PDUs.</li>\n<li><code>ecuExtractVersion: RevisionLabelString [0..1]</code> – Versionsstand des abgeleiteten ECU-Extracts.</li>\n<li><code>pncVectorLength: PositiveInteger [0..1]</code> & <code>pncVectorOffset: PositiveInteger [0..1]</code> – Dimensionierung und Offset des Partial-Network-Cluster-Bitvektors.</li>\n<li><code>systemVersion: RevisionLabelString [0..1]</code> – Optionale Version der System Description.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):</li>\n</ul>\n<p class=\"fig-p\">Top-Level-Prototyp der gesamten Software-Architektur des Systems.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompositionSwComponentType</code></strong> (<code>«SwComponentType»</code>):</li>\n</ul>\n<p class=\"fig-p\">Hierarchischer Kompositionstyp, der Sub-Komponenten bündelt.</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):</li>\n</ul>\n<p class=\"fig-p\">Konkrete Komponenten-Instanz innerhalb einer Komposition.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CpSoftwareCluster</code></strong> (<code>«ARElement»</code>):</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert die Kapselungseinheit für Classic Platform Software-Cluster (<code>mmt.RestrictToStandards = CP</code>).</p>\n<ul class=\"fig-list\">\n<li><em>Attribute:</em></li>\n<li><code>softwareClusterId: PositiveInteger [0..1]</code> – Optionale eindeutige numerische Kennung des Software-Clusters.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>SwComponentPrototypeAssignment</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Dediziertes Mapping-Element zur feingranularen Zuweisung eines Komponenten-Prototyps zu einem Cluster via Instanzreferenz.</p>\n<p class=\"fig-p\">#### Beziehungen, Kardinalitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>System</code> ➔ <code>RootSwCompositionPrototype</code> (<code>+rootSoftwareComposition</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>. Definiert die primäre Software-Komposition des Systems.</p>\n<ul class=\"fig-list\">\n<li><strong><code>RootSwCompositionPrototype</code> ➔ <code>CompositionSwComponentType</code> (<code>+softwareComposition</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Typisierung via <code>«isOfType»</code> unter <code>{redefines atpType}</code> mit Multiplizität 0..1.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>CompositionSwComponentType</code> ➔ <code>SwComponentPrototype</code> (<code>+component</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>. Enthält die Komponentenprototypen des Software-Designs.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>System</code> ➔ <code>CpSoftwareCluster</code> (<code>+swCluster</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Referenzierende Aggregation mit <code>«atpSplitable, atpVariation»</code>. Bindet beliebig viele Cluster an das System.</p>\n<ul class=\"fig-list\">\n<li>*<em><code>CpSoftwareCluster</code> ➔ <code>CompositionSwComponentType</code> (<code>+swComposition</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Assoziation mit <code>«atpVariation, atpSplitable»</code>.</p>\n<ul class=\"fig-list\">\n<li><em>Tag:</em> <code>vh.latestBindingTime = systemDesignTime</code>. Ganze Kompositionsstrukturen werden früh zur Systementwurfszeit an den Cluster gebunden.</li>\n<li>*<em><code>CpSoftwareCluster</code> ➔ <code>SwComponentPrototypeAssignment</code> (<code>+swComponentAssignment</code>, 0..</em>):**</li>\n</ul>\n<p class=\"fig-p\">Komposition mit <code>«atpVariation, atpSplitable»</code>.</p>\n<ul class=\"fig-list\">\n<li><em>Tag:</em> <code>vh.latestBindingTime = postBuild</code>. Erlaubt späte, instanzbezogene Cluster-Zuordnungen bis zur Post-Build-Phase.</li>\n<li><strong><code>SwComponentPrototypeAssignment</code> ➔ <code>SwComponentPrototype</code> (<code>+swComponent</code>, 0..1):</strong></li>\n</ul>\n<p class=\"fig-p\">Gerichtete Assoziation via Instanzreferenz (<code>«instanceRef»</code>). Referenziert den spezifischen Komponenten-Prototyp im Architekturbaum.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein M2-Klassendiagramm der Informationsarchitektur handelt, existiert kein Ausführungsablauf zur CPU-Laufzeit. Der methodische Verarbeitungsablauf im AUTOSAR-Workflow gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>System Design Time:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Modellierung der VFB-Architektur (<code>RootSwCompositionPrototype</code>, <code>CompositionSwComponentType</code>).</li>\n<li>Grobe Cluster-Zuweisung vollständiger Funktionsbündel über <code>CpSoftwareCluster.swComposition</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ECU Partitioning & Post-Build Configuration:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Granulare Bindung einzelner Komponentenprototypen über <code>SwComponentPrototypeAssignment</code> (<code>«instanceRef»</code>).</li>\n<li>Auflösung von Varianten (<code>atpVariation</code>) bis zur Bindungszeit <code>postBuild</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Build & Toolchain:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Extraktion der Cluster-Artefakte für getrennte RTE-, OS- und Memory-Protection-Generierung pro Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Gültigkeit & Normativer Kontext:</strong> Die Modellierung definiert die formale Struktur zur Abbildung von Software-Clustern der Classic Platform (<code>mmt.RestrictToStandards = CP</code>) innerhalb einer AUTOSAR-Systembeschreibung (<code>System</code>). Das <code>System</code> ist zudem als <code>«UploadableDesignElement»</code> qualifiziert.</li>\n<li><strong>Optionale Wurzelelemente:</strong> Sowohl die Versionsangabe des Gesamtsystems (<code>systemVersion</code>) als auch die Typisierung der Software-Wurzelkomposition (<code>+softwareComposition</code>) besitzen die Kardinalität <code>0..1</code>, was eine flexible, schrittweise Befüllung des Metamodells im Systementwurf erlaubt.</li>\n<li><strong>Variabilitätsmanagement:</strong> Sowohl die Aggregation der Cluster am System (<code>+swCluster</code>) als auch die Zuordnungen von Kompositionen (<code>+swComposition</code>) und Komponenten-Prototypen (<code>+swComponentAssignment</code>) sind als <code>«atpSplitable»</code> und <code>«atpVariation»</code> modelliert. Cluster-Definitionen können somit über mehrere ARXML-Dateien fragmentiert und über Systemvarianten hinweg konditioniert werden.</li>\n<li><strong>Instanzreferenzen:</strong> Bei <code>SwComponentPrototypeAssignment</code> handelt es sich um eine Instanzreferenz (<code>«instanceRef»</code>) auf einen <code>SwComponentPrototype</code>, die den vollen hierarchischen Kontext innerhalb der Wurzelkomposition auflösen muss.</li>\n</ul>"}], "trans": [{"from": "FIG-6245b9b175d08eb5", "to": "FIG-f47a9b1b798782f7", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>CpSoftwareCluster</strong>: Attribut <code>+ softwareClusterId: PositiveInteger [0..1]</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-f47a9b1b798782f7", "to": "FIG-1cd4117d26638a32", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>System</strong>: Stereotyp <code>«UploadableDesignElement»</code> hinzugefügt.</li>\n<li><strong>System</strong>: Multiplizität des Attributs <code>systemVersion</code> von <code>systemVersion: RevisionLabelString</code> (implizit <code>[1]</code>) zu <code>systemVersion: RevisionLabelString [0..1]</code> geändert.</li>\n<li><strong>RootSwCompositionPrototype ➔ CompositionSwComponentType</strong>: Multiplizität der Assoziation <code>+softwareComposition</code> von <code>1</code> zu <code>0..1</code> geändert.</li>\n<li><strong>CpSoftwareCluster</strong>: Tag <code>atp.Status = draft</code> in beiden Variationspunkt-Kommentarfeldern entfernt.</li>\n</ul>"}, {"from": "FIG-1cd4117d26638a32", "to": "FIG-5ec3261557780e43", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>CpSoftwareCluster</strong>: Reihenfolge der Tags in den beiden Variationspunkt-Kommentarfeldern umgestellt (<code>vh.latestBindingTime</code> steht nun vor <code>mmt.RestrictToStandards = CP</code>).</li>\n</ul>"}, {"from": "FIG-5ec3261557780e43", "to": "FIG-8425c712128c68a7", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
